import { EditorFrame, Badge } from "march/ui"

// haiku defteri: çerçevenin alt çubuğu satırları sayar; üç satır olunca çerçeve yeşile döner
export function HaikuPad() {
  let $text = "Sessiz göl kıyı\nbir kurbağa atlıyor"
  const $lines = $text.split("\n").filter((l) => l.trim()).length
  return <EditorFrame m:color={$lines === 3 ? "success" : "brand-purple"}
    head={<span sx={{ text: "bold" }}>Haiku</span>}
    actions={<Badge tone={$lines === 3 ? "success" : "neutral"}>{`${$lines} / 3 satır`}</Badge>}
    foot={<span>{$lines === 3 ? "Tamam, şiir hazır" : "Üç kısa satır yazın"}</span>}>
    <textarea class="m-editor-area" rows={3} aria-label="Haiku" value={$text}
      on:input={(e: Event) => $text = (e.target as HTMLTextAreaElement).value} />
  </EditorFrame>
}

import { EditorFrame, Badge, Button, toast } from "march/ui"

// destek yanıtı: üstte talep ve öncelik, ortada yanıt, altta sayaç ve Gönder; gönderilince çerçeve salt okunur olur
const MAX = 500

export function SupportReply() {
  let $text = "Merhaba Ayşe Hanım, siparişiniz yarın kargoya veriliyor."
  let $sent = false
  const send = () => { $sent = true; toast("Yanıt müşteriye gönderildi") }
  return <EditorFrame readonly={$sent}
    head={<span sx={{ text: "bold" }}>Talep #4821 · Kargo gecikmesi</span>}
    actions={<Badge tone={$sent ? "success" : "warn"}>{$sent ? "Yanıtlandı" : "Bekliyor"}</Badge>}
    foot={<span sx={{ color: $text.length > MAX ? "danger" : "muted" }}>{`${$text.length} / ${MAX}`}</span>}
    footProps={{ actions: <Button size="sm" disabled={$sent || !$text.trim() || $text.length > MAX} on:click={send}>Gönder</Button> }}>
    <textarea class="m-editor-area" rows={4} aria-label="Yanıt" readonly={$sent} value={$text}
      on:input={(e: Event) => $text = (e.target as HTMLTextAreaElement).value} />
  </EditorFrame>
}

import { EditorFrame, FormatToolbar, Badge, Button, Card } from "march/ui"

// EditorFrame'in bütün özellikleri: üst çubuk içeriği ve eylemleri, gösterilip gizlenmesi (showHead / showFoot),
// çubukların kendi özellikleri (headProps / footProps), alt çubuk, devre dışı ve salt okunur (erişimci), odak halkası,
// sınıf, içerik (children) ve öteki öznitelikler (id, data-*)
export function EditorFrameLab() {
  let $text = "Bir not"
  let $tools = true
  let $mode = "edit" as "edit" | "readonly" | "disabled"
  let $last = ""
  return <div sx={{ flex: "col", gap: 3 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" variant="secondary" on:click={() => $tools = !$tools}>{$tools ? "Araçları gizle" : "Araçları göster"}</Button>
      <Button size="sm" variant="secondary" on:click={() => $mode = $mode === "edit" ? "readonly" : $mode === "readonly" ? "disabled" : "edit"}>{`Durum: ${$mode}`}</Button>
    </div>
    <EditorFrame id="lab-frame" data-kind="note" class="lab-frame" m:color="brand-orange"
      head={<FormatToolbar tools={["bold", "italic"]} onTool={(t) => $last = t} />}
      actions={() => <Badge tone="neutral">{`${$text.length} harf`}</Badge>}
      showHead={() => $tools} headProps={{ sticky: true, class: "lab-head", "aria-label": "Not araçları" }}
      foot={<span>{$last ? `Son araç: ${$last}` : "Bir araca basın"}</span>}
      showFoot={() => $mode !== "disabled"} footProps={{ divider: true, class: "lab-foot", "aria-live": "polite" }}
      readonly={() => $mode === "readonly"} disabled={() => $mode === "disabled"}>
      <textarea class="m-editor-area" rows={3} aria-label="Not" value={$text} readonly={$mode === "readonly"} disabled={$mode === "disabled"}
        on:input={(e: Event) => $text = (e.target as HTMLTextAreaElement).value} />
    </EditorFrame>
    <Card m:theme="night">
      <EditorFrame ring={false} showFoot={false} foot="görünmez" class="lab-plain">
        <textarea class="m-editor-area" rows={2} aria-label="Halkasız not" />
      </EditorFrame>
    </Card>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { EditorFrameLab } from "./EditorFrameLab.tsx"

// EditorFrameLab'in testleri: kaydedince Testler sekmesinde çalışır
test("üst ve alt çubuk, kendi sınıfları ve öznitelikleriyle çizilir", () => {
  const s = renderTest(() => <EditorFrameLab />)
  const frame = s.get("#lab-frame")
  expect(frame?.getAttribute("data-kind")).toBe("note")
  expect(frame?.querySelector(".lab-head")).not.toBe(null)
  expect(frame?.querySelector(".lab-foot")?.getAttribute("aria-live")).toBe("polite")
  expect(s.sees("7 harf")).toBe(true)
})

test("showHead erişimcisi üst çubuğu gizler ve geri getirir", async () => {
  const s = renderTest(() => <EditorFrameLab />)
  await s.click("Araçları gizle")
  expect(s.get("#lab-frame .lab-head")).toBe(null)
  await s.click("Araçları göster")
  expect(s.get("#lab-frame .lab-head")).not.toBe(null)
})

test("durum: salt okunur, sonra devre dışı (alt çubuk da gider)", async () => {
  const s = renderTest(() => <EditorFrameLab />)
  await s.click("Durum: edit")
  expect(s.get("#lab-frame")?.className).toContain("is-readonly")
  await s.click("Durum: readonly")
  expect(s.get("#lab-frame")?.className).toContain("is-disabled")
  expect(s.get("#lab-frame .lab-foot")).toBe(null)
})

test("ring={false} halkasız, showFoot={false} foot'u gizler", () => {
  const s = renderTest(() => <EditorFrameLab />)
  expect(s.get(".lab-plain")?.className).toContain("is-plain")
  expect(s.sees("görünmez")).toBe(false)
})
